    [data-theme="light"] {
      color-scheme: light;
      --bg: #FFF8E7;
      --text: #1D1D1F;
      --muted: #5A5A5F;
      --card: #FFFFFF;
      --border: #e5dcc9;
      --shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
      --header-tint: #f8eada;
      --link: #75401f;
      --focus: #075e9b;
    }

    [data-theme="dark"] {
      color-scheme: dark;
      --bg: #14142B;
      --text: #F4F1DE;
      --muted: #B8B5A7;
      --card: #1F1F3D;
      --border: #393957;
      --shadow: none;
      --header-tint: #211c35;
      --link: #efb98f;
      --focus: #ffd18c;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      background: var(--bg);
      color: var(--text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      font-size: 1rem;
      line-height: 1.65;
      transition: background-color 180ms ease, color 180ms ease;
    }

    a {
      color: var(--link);
      text-underline-offset: 0.2em;
    }

    a:hover {
      text-decoration-thickness: 0.15em;
    }

    :focus-visible {
      outline: 0.2rem solid var(--focus);
      outline-offset: 0.2rem;
      border-radius: 0.2rem;
    }

    .site-header {
      background: linear-gradient(135deg, var(--bg), var(--header-tint));
      border-bottom: 1px solid var(--border);
    }

    .header-inner {
      position: relative;
      width: min(100% - 3rem, 70rem);
      min-height: 19rem;
      margin-inline: auto;
      padding: 4.25rem 0 3.5rem;
      display: flex;
      align-items: center;
    }

    .intro {
      max-width: 46rem;
      padding-right: 5rem;
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--muted);
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    h1, h2, h3, p {
      margin-top: 0;
    }

    h1 {
      margin-bottom: 0.5rem;
      font-size: clamp(2.5rem, 6vw, 4.5rem);
      line-height: 1.05;
      letter-spacing: -0.045em;
    }

    .tagline {
      margin: 0;
      color: var(--muted);
      font-size: 1.2rem;
    }

    #theme-toggle {
      position: absolute;
      top: 1.5rem;
      right: 0;
      min-width: 3rem;
      min-height: 3rem;
      padding: 0.5rem 0.8rem;
      border: 1px solid var(--border);
      border-radius: 999px;
      background: var(--card);
      color: var(--text);
      font: inherit;
      font-size: 1.25rem;
      cursor: pointer;
      box-shadow: var(--shadow);
    }

    #theme-toggle:hover {
      border-color: var(--accent);
    }

    main {
      width: min(100% - 3rem, 70rem);
      margin-inline: auto;
    }

    section {
      padding-block: 4rem;
    }

    .section-heading {
      max-width: 46rem;
      margin-bottom: 2rem;
    }

    .section-heading h2 {
      margin-bottom: 0.6rem;
      font-size: clamp(1.8rem, 4vw, 2.5rem);
      line-height: 1.15;
      letter-spacing: -0.025em;
    }

    .section-heading p {
      margin-bottom: 0;
      color: var(--muted);
      font-size: 1.075rem;
    }

    .member-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
      gap: 1.5rem;
    }

    .member-card {
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      min-width: 0;
      padding: 1.5rem;
      border: 1px solid var(--border);
      border-radius: 1rem;
      background: var(--card);
      box-shadow: var(--shadow);
    }

    .member-card img {
      display: block;
      width: 8rem;
      height: 8rem;
      margin-bottom: 1.1rem;
      border: 3px solid var(--bg);
      border-radius: 50%;
      object-fit: cover;
    }

    .member-card h3 {
      margin-bottom: 0.25rem;
      font-size: 1.4rem;
      line-height: 1.25;
    }

    .study {
      margin-bottom: 0.85rem;
      color: var(--muted);
      font-size: 0.9rem;
      font-weight: 600;
    }

    .bio {
      margin-bottom: 1.1rem;
      font-size: 0.96rem;
    }

    .linkedin {
      margin-top: auto;
      margin-bottom: 1rem;
      font-size: 0.9rem;
      font-weight: 650;
    }

    .hot-take {
      width: 100%;
      margin: 0;
      padding: 0.75rem 0.85rem;
      border-radius: 0.65rem;
      background: var(--accent);
      color: #ffffff;
      font-size: 0.9rem;
      font-weight: 700;
      line-height: 1.45;
    }

    #future-of-se {
      padding-top: 1.5rem;
    }

    .future-panel {
      padding: clamp(1.5rem, 4vw, 2.5rem);
      border: 1px solid var(--border);
      border-radius: 1rem;
      background: var(--card);
      box-shadow: var(--shadow);
    }

    .future-panel h2 {
      margin-bottom: 1rem;
      font-size: clamp(1.8rem, 4vw, 2.5rem);
      line-height: 1.15;
      letter-spacing: -0.025em;
    }

    .future-panel p {
      max-width: 62rem;
      margin-bottom: 1rem;
    }

    .future-panel p:last-child {
      margin-bottom: 0;
    }

    .future-panel strong {
      color: var(--accent);
    }

    footer {
      margin-top: 1rem;
      padding: 1.5rem 1rem;
      border-top: 1px solid var(--border);
      color: var(--muted);
      text-align: center;
      font-size: 0.875rem;
    }

    footer p {
      margin: 0;
    }

    @media (max-width: 700px) {
      .header-inner {
        width: 100%;
        min-height: auto;
        padding: 5rem 1rem 2.5rem;
        flex-direction: column;
        align-items: flex-start;
      }

      .intro {
        padding-right: 0;
      }

      #theme-toggle {
        top: 1rem;
        right: 1rem;
      }

      main {
        width: calc(100% - 2rem);
      }

      section {
        padding-block: 3rem;
      }

      .member-grid {
        grid-template-columns: 1fr;
      }

      #future-of-se {
        padding-top: 0.5rem;
      }
